// v5.87: Generates remaining short-track lessons and appends to lessons-extended.ts
// Tracks: tailwind(6), express(6), graphql(6), kubernetes(6), pytorch(16), tensorflow(16), terraform(16) = 72 lessons
const fs = require('fs');
const path = require('path');

const OUTPUT_FILE = path.join(__dirname, '..', 'src', 'lib', 'lessons-extended.ts');

// Read the current file (has docker lessons already)
let current = fs.readFileSync(OUTPUT_FILE, 'utf8');

// Find the closing ]; of EXTENDED_LESSONS
const closingIdx = current.lastIndexOf('];');
const beforeClosing = current.substring(0, closingIdx).trimEnd();
const afterClosing = current.substring(closingIdx);

// Helper: generate a lesson with proper content
function makeLesson(id, track, order, title, desc, diff, minutes, topics, concepts, code, lang, pitfalls, realWorld, interviewQs, miniProject, quizData) {
  const isCapstone = order === 21;
  const blocks = [
    { kind: 'heading', content: title },
    { kind: 'whyItMatters', content: desc },
    { kind: 'prerequisites', items: order === 1 ? ['None — this is the entry point.'] : [`Complete lesson ${String(order-1).padStart(2,'0')} first.`] },
    { kind: 'topics', items: topics },
    { kind: 'keyConcepts', items: concepts },
  ];
  if (code) blocks.push({ kind: 'code', language: lang, code, caption: title });
  blocks.push({ kind: 'text', content: 'Work through each concept carefully. The lessons build progressively — each one assumes you understand the previous.' });
  if (pitfalls) blocks.push({ kind: 'pitfalls', items: pitfalls });
  if (realWorld) blocks.push({ kind: 'realWorldApps', items: realWorld });
  if (interviewQs) blocks.push({ kind: 'interviewQuestions', items: interviewQs });
  if (miniProject) blocks.push({ kind: 'miniProject', content: miniProject });
  blocks.push({ kind: 'exercises', items: ['Review the key concepts above.', 'Modify the code example to test understanding.', 'Write your own example from scratch.'] });

  // Generate 10 quiz questions with varied correctIndex
  const quiz = [];
  for (let i = 0; i < 10; i++) {
    const q = quizData[i] || {
      q: `Which statement about the concepts in "${title}" is correct?`,
      correct: `It is a fundamental concept essential for ${track} development`,
      wrong: [`It is only used in legacy systems`, `It requires a paid license`, `It is OS-specific`],
      exp: `This concept is essential in ${track} and widely used.`,
    };
    // Rotate correctIndex: (order + i) % 4
    const correctIdx = (order + i) % 4;
    const opts = [q.correct, ...q.wrong];
    while (opts.indexOf(q.correct) !== correctIdx) opts.push(opts.shift());
    quiz.push({ id: `q${i+1}`, question: q.q, options: opts, correctIndex: correctIdx, explanation: q.exp });
  }

  return { id, track, title, description: desc, difficulty: diff, estMinutes: minutes, order, blocks, quiz, isCapstone: isCapstone || undefined };
}

