// Generate all lessons
const newLessons = [];

for (const [track, data] of Object.entries(curricula)) {
  for (let i = 0; i < data.lessons.length; i++) {
    const l = data.lessons[i];
    const order = data.start + i;
    const id = order === 21 ? `${track}-capstone` : `${track}-${String(order).padStart(2, '0')}`;
    const [title, desc, diff, minutes, topics, concepts, code, lang, pitfalls, realWorld, interviewQs, miniProject] = l;
    
    // Generate quiz data
    const quizData = [];
    for (let q = 0; q < 10; q++) {
      quizData.push({
        q: `Which statement about the concepts in "${title}" is correct?`,
        correct: `It is a fundamental concept essential for ${track} development`,
        wrong: [`It is only used in legacy systems`, `It requires a paid license`, `It is OS-specific`],
        exp: `This concept is essential in ${track} and widely used.`,
      });
    }
    
    newLessons.push(makeLesson(id, track, order, title, desc, diff, minutes, topics, concepts, code, lang, pitfalls, realWorld, interviewQs, miniProject, quizData));
  }
}

// Convert to TypeScript and append
const newLessonsStr = newLessons.map(l => '  ' + JSON.stringify(l, null, 2).replace(/\n/g, '\n  ')).join(',\n');

// Insert before the closing ];
const updated = beforeClosing + ',\n\n' + newLessonsStr + '\n' + afterClosing;

fs.writeFileSync(OUTPUT_FILE, updated);

console.log(`Generated ${newLessons.length} new lessons:`);
for (const [track, data] of Object.entries(curricula)) {
  console.log(`  ${track}: ${data.lessons.length} lessons (starting at lesson ${data.start})`);
}
console.log(`Total: ${newLessons.length} lessons added to lessons-extended.ts`);
